scwin.vScrenID = "ULDINS25200.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    $c.cm.PanelToGroupBox(panel_2);
    var array_grid = [grd_List];
    setResizeGrid(array_grid);

    // 콤보 세팅.
    scwin.fn_SetCombo();

    // 기본값 세팅
    scwin.fn_SetDefaultVal();
};


/**
 *  콤보박스 만들기
 */
scwin.fn_SetCombo = function() {
    ins_combo_set(dts_BND_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "01422", "ALL"); //채권유형 
    ins_combo_set(dts_INT_PAY_METHD_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "00872", "ALL"); //이자지급방법코드 		
    ins_combo_set(dts_LIST_STAT_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "00714", "ALL"); //상장상태코드 		
    ins_combo_set(dts_ASST_SECUTIZ_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03075", "ALL"); //자산유동화구분코드 
    ins_combo_set(dts_MUNIBND_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03076", "ALL"); //지방채구분코드 		
    ins_combo_set(dts_NUSUAL_BND_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03221", "ALL"); //특이채권유형코드 
    ins_combo_set(dts_IMBDOPT_CORPBND_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "03054", "ALL"); //옵션부사채코드 
    ins_combo_set(dts_BND_DELIST_RSN_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "01515", "ALL"); //채권상장폐지사유코드 
    //ins_combo_set(dts_SRI_BND_TP_CD, vScrenID, SCREN_PROCS_TP_CD_01 ,"04427","ALL"); //SRI채권구분

};



/**
 *  화면의 기본값 세팅
 */
scwin.fn_SetDefaultVal = function() {
    var sToday = $c.ut.cGetToday2();
    edt_FROM_ISU_DD.setValue($c.ut.cGetPlusDate2($c.ut.cGetMinusYear(sToday, 1), 1));
    edt_TO_ISU_DD.setValue(sToday);
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_List.removeAll();
};


/**
 * 채권조회
 */
scwin.ins_search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // 조회조건 체크.
    tab_Info.setSelectedTabIndex("2");

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_List);

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20210528
    btn_search.setDisabled(true);
    btn_search.src = "../img/btn_select_d.gif";
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.down.select.listStdCdBndDownLoadInquiry" + "&outputMessageId=INS_LIST_STDCD_BND_DOWNLOAD_INQUIRY" + "&{P}BND_TP_CD=" + $c.stf.getObjectValue(cmb_BND_TP_CD) + "&{P}BND_TP_CD_OP=" + $c.stf.getObjectValue(cmb_Oper1) + "&{P}INT_PAY_METHD_CD=" + $c.stf.getObjectValue(cmb_INT_PAY_METHD_CD) + "&{P}INT_PAY_METHD_CD_OP=" + $c.stf.getObjectValue(cmb_Oper2) + "&{P}LIST_STAT_CD=" + $c.stf.getObjectValue(cmb_LIST_STAT_CD) + "&{P}LIST_STAT_CD_OP=" + $c.stf.getObjectValue(cmb_Oper3) + "&{P}ISUR_CD_FROM=" + $c.stf.getObjectValue(txb_FROM_ISUR_CD) + "&{P}ISUR_CD_TO=" + $c.stf.getObjectValue(txb_TO_ISUR_CD) + "&{P}ASST_SECUTIZ_TP_CD=" + $c.stf.getObjectValue(cmb_ASST_SECUTIZ_TP_CD) + "&{P}ASST_SECUTIZ_TP_CD_OP=" + $c.stf.getObjectValue(cmb_Oper4) + "&{P}MUNIBND_TP_CD=" + $c.stf.getObjectValue(cmb_MUNIBND_TP_CD) + "&{P}MUNIBND_TP_CD_OP=" + $c.stf.getObjectValue(cmb_Oper5) + "&{P}BND_DELIST_RSN_CD=" + $c.stf.getObjectValue(cmb_BND_DELIST_RSN_CD) + "&{P}BND_DELIST_RSN_CD_OP=" + $c.stf.getObjectValue(cmb_Oper6) + "&{P}NUSUAL_BND_TP_CD=" + $c.stf.getObjectValue(cmb_NUSUAL_BND_TP_CD) + "&{P}NUSUAL_BND_TP_CD_OP=" + $c.stf.getObjectValue(cmb_Oper7) + "&{P}ACTIV_TP_CD=" + $c.stf.getObjectValue(cmb_ACTIV_TP_CD) + "&{P}IMBDOPT_CORPBND_CD=" + $c.stf.getObjectValue(cmb_IMBDOPT_CORPBND_CD) + "&{P}IMBDOPT_CORPBND_CD_OP=" + $c.stf.getObjectValue(cmb_Oper8) + "&{P}ISU_DD_FROM=" + $c.stf.getObjectValue(edt_FROM_ISU_DD) + "&{P}ISU_DD_TO=" + $c.stf.getObjectValue(edt_TO_ISU_DD) + "&{P}STD_CD_GRNT_DD_FROM=" + $c.stf.getObjectValue(edt_FROM_STD_CD_GRNT_DD) + "&{P}STD_CD_GRNT_DD_TO=" + $c.stf.getObjectValue(edt_TO_STD_CD_GRNT_DD) + "&{P}SRI_BND_TP_CD=" + $c.stf.getObjectValue(cmb_SRI_BND_TP_CD) + "&{P}SRI_BND_TP_CD_OP=" + $c.stf.getObjectValue(cmb_Oper9);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};


/**
 * 사전체크
 */
scwin.fn_ChkValid = function() {
    // 발행기관코드 체크
    if (($c.stf.getObjectValue(txb_FROM_ISUR_CD) != "" && $c.stf.getObjectValue(txb_TO_ISUR_CD) != "") &&
        ($c.stf.getObjectValue(txb_FROM_ISUR_CD) > $c.stf.getObjectValue(txb_TO_ISUR_CD))) {
        $c.win.alert("검색시작 발행기관코드가 종료 발행기관코드보다 큽니다.");
        txb_FROM_ISUR_CD.focus();
        return false;
    }

    // 상장여부가 전체, 비상장, 상장폐지인 경우 발행일 또는 코드부여일이 필수이고 1년 이내로 입력해야함.
    var sListStat = $c.stf.getObjectValue(cmb_LIST_STAT_CD);
    if (sListStat == "" || sListStat == "D" || sListStat == "N") {
        if (($c.stf.getObjectValue(edt_FROM_ISU_DD) == "" || $c.stf.getObjectValue(edt_TO_ISU_DD) == "") &&
            ($c.stf.getObjectValue(edt_FROM_STD_CD_GRNT_DD) == "" || $c.stf.getObjectValue(edt_TO_STD_CD_GRNT_DD) == "")) {
            $c.win.alert(" 상장여부가 [전체, 비상장, 상장폐지] 인 경우 \n 발행일 또는 코드부여일을 1년 이내로 입력해야 합니다.");
            edt_FROM_ISU_DD.focus();
            return false;
        } else {
            // 발행일, 또는 코드부여일이 입력되었다.
            // 1년 이내 체크.
            if (($c.stf.getObjectValue(edt_FROM_ISU_DD) != "" && $c.stf.getObjectValue(edt_TO_ISU_DD) != "") &&
                eval($c.ut.cGetPlusYear(edt_FROM_ISU_DD.getValue(), 1)) < eval(edt_TO_ISU_DD.getValue())) {
                $c.win.alert("발행일의 검색 기간은 1년 이내로만 가능합니다.");
                edt_FROM_ISU_DD.focus();
                return false;
            }
            if (($c.stf.getObjectValue(edt_FROM_STD_CD_GRNT_DD) != "" && $c.stf.getObjectValue(edt_TO_STD_CD_GRNT_DD) != "") &&
                eval($c.ut.cGetPlusYear(edt_FROM_STD_CD_GRNT_DD.getValue(), 1)) < eval(edt_TO_STD_CD_GRNT_DD.getValue())) {
                $c.win.alert("코드부여일의 검색 기간은 1년 이내로만 가능합니다.");
                edt_FROM_STD_CD_GRNT_DD.focus();
                return false;
            }
        }
    }

    // 발행일 체크
    if ($c.stf.compareFromToDate2(edt_FROM_ISU_DD, edt_TO_ISU_DD) == false) {
        return false;
    }
    // 코드부여일 체크
    if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_GRNT_DD, edt_TO_STD_CD_GRNT_DD) == false) {
        return false;
    }
    return true;
};


/**
 * 체크박스 체크 시 그리드 항목 show
 */
scwin.fn_GridCtrl = function(pObj) {
    var sColId = pObj.id;
    sColId = sColId.replace("chb_", "");
    var bChecked = $c.stf.getObjectValue(pObj);
    if (bChecked == "Y" && $c.cm.getColumnProp(grd_List, sColId, "Show") != "TRUE") {
        $c.cm.setColumnProp(grd_List, sColId, "Show", true);
    } else if (bChecked == "N" && $c.cm.getColumnProp(grd_List, sColId, "Show") == "TRUE") {
        $c.cm.setColumnProp(grd_List, sColId, "Show", false);
    }
};



/**
 * 전체선택 체크 시 나머지 모두 언체크.
 */
scwin.fn_AllUnCheck = function() {
    var sAllChecked = $c.stf.getObjectValue(chb_ALL);
    $c.stf.setObjectValue(chb_CFI_CD, sAllChecked);
    $c.stf.setObjectValue(chb_SRI_BND_TP_CD, sAllChecked);
    $c.stf.setObjectValue(chb_SRI_BND_APPL_TP_CD, sAllChecked);
    scwin.fn_GridCtrl(chb_CFI_CD);
    scwin.fn_GridCtrl(chb_SRI_BND_TP_CD);
    scwin.fn_GridCtrl(chb_SRI_BND_APPL_TP_CD);
    for (var i = 1; i < 12; i++) {
        var checkObject = eval("ckb_G" + i);
        $c.stf.setObjectValue(checkObject, sAllChecked);
        scwin.fn_GroupCheck(checkObject);
    }
};




/**
 * 필수항목 선택 체크 시 필수값만 체크되도록..
 */
scwin.fn_NssryCheck = function() {
    var arrayNssry = ["ISUR_CD", "COM_NM", "LIST_DD", "BND_TP", "BND_CLSS_CD", "BND_CLSS_NM", "ISU_KOR_NM", "ISU_AMT", "ISU_DD", "ISU_ENG_NM", "REDMPT_DD", "CURR_TP", "INT_PAY_METHD", "COUPN_RT"];
    var pChecked = $c.stf.getObjectValue(chb_NSSRY);

    // 전체 초기화
    $c.stf.setObjectValue(chb_ALL, "N");
    scwin.fn_AllUnCheck();
    for (var i = 0; i < arrayNssry.length; i++) {
        if (pChecked == "Y") {
            $c.cm.setColumnProp(grd_List, arrayNssry[i], "Show", true);
        } else {
            $c.cm.setColumnProp(grd_List, arrayNssry[i], "Show", false);
        }
        $c.stf.setObjectValue(eval("chb_" + arrayNssry[i]), pChecked);
    }
};



/**
 * 각 그룹별로 전체체크 또는 언체크..
 */
scwin.fn_GroupCheck = function(groupChk) {
    var chk_name = groupChk.name.split("_g")[1];
    var sAllChecked = $c.stf.getObjectValue(groupChk);
    var oCheckBoxs = document.getElementsByName("ckb_" + chk_name);
    for (var nRow = 0; nRow < oCheckBoxs.length; nRow++) {
        oCheckBoxs[nRow].setValue((sAllChecked == "Y") ? true : false);
        scwin.fn_GridCtrl(oCheckBoxs[nRow]);
    }
};




/**
 * 상장상태가 [전체, 비상장, 상장폐지]인 경우 일자를 기본값으로 세팅.
 */
scwin.fn_SetSrchDt = function() {
    if ($c.stf.getObjectValue(cmb_LIST_STAT_CD) == "" || $c.stf.getObjectValue(cmb_LIST_STAT_CD) == "D" || $c.stf.getObjectValue(cmb_LIST_STAT_CD) == "N") {
        if (($c.stf.getObjectValue(edt_FROM_ISU_DD) == "" || $c.stf.getObjectValue(edt_TO_ISU_DD) == "") &&
            ($c.stf.getObjectValue(edt_FROM_STD_CD_GRNT_DD) == "" || $c.stf.getObjectValue(edt_TO_STD_CD_GRNT_DD) == "")) {
            // 기본값 세팅
            scwin.fn_SetDefaultVal();
        }
    }
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.dts_List_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_List);
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_List);

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20210528
    btn_search.setDisabled(false);
    btn_search.src = "../img/btn_select.gif";
};
scwin.btn_Excel_onclick = function() {
    if (dts_List.getTotalRow() <= 0) {
        $c.win.alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 로그 남기고..	

    var today = $c.ut.cGetToday("yyyymmddhhmmss");
    var title = "채권다운로드";
    var xls_path = $c.session.getExcelDownPath() + today + "_" + title + ".xls";
    $c.data.downloadGridViewOffice(grd_List, title, xls_path, 8, 0);
    //grd_List.GridToExcel(title, "", "8");

};
